package dev.noveris.letter.client;

import net.minecraft.client.Minecraft;
import net.minecraft.client.renderer.texture.DynamicTexture;
import net.minecraft.client.renderer.texture.TextureManager;
import net.minecraft.resources.ResourceLocation;
import com.mojang.blaze3d.platform.NativeImage;

import java.io.ByteArrayInputStream;
import java.util.Base64;

import static dev.noveris.letter.NoverisLetter.MOD_ID;

/** Registers the original flight textures from the user-provided Frikinzi's Fauna archive. */
public final class CourierTextures {
    public static final ResourceLocation RAVEN_FLY_TEXTURE = ResourceLocation.fromNamespaceAndPath(MOD_ID, "generated/courier/raven_fly");
    public static final ResourceLocation SPARROW_FLY_TEXTURE = ResourceLocation.fromNamespaceAndPath(MOD_ID, "generated/courier/sparrow_fly");
    public static final ResourceLocation BARN_OWL_FLY_TEXTURE = ResourceLocation.fromNamespaceAndPath(MOD_ID, "generated/courier/barnowl_fly");

    private static final String RAVEN_FLY = "";
    private static final String SPARROW_FLY = "?";
    private static final String BARN_OWL_FLY = "";

    private CourierTextures() { }

    public static void register() {
        TextureManager manager = Minecraft.getInstance().getTextureManager();
        register(manager, RAVEN_FLY_TEXTURE, RAVEN_FLY);
        register(manager, SPARROW_FLY_TEXTURE, SPARROW_FLY);
    }

    private static void register(TextureManager manager, ResourceLocation id, String encoded) {
        try {
            NativeImage image = NativeImage.read(new ByteArrayInputStream(Base64.getDecoder().decode(encoded)));
            manager.register(id, new DynamicTexture(image));
        } catch (Exception e) {
            throw new IllegalStateException("Could not register courier flight texture " + id, e);
        }
    }
}
